value.stringValue:
The FQS Stewardship Response scheduled flow encountered an error while processing a GiftTransaction record.

Error: {!$Flow.FaultMessage}

Interview: {!$Flow.CurrentDateTime}

formulas.expression:
"Personal stewardship outreach needed. Donor lifetime tier: " &
IF(ISBLANK({!Get_DonorGiftSummary.FQS_Lifetime_Donor_Level_Name__c}),
  "None on record",
  {!Get_DonorGiftSummary.FQS_Lifetime_Donor_Level_Name__c}
) & ". Email opt-out: " & IF({!Get_Contact.HasOptedOutOfEmail}, "Yes", "No") & "."
